import React, { useState, useEffect } from 'react';
import './App.css';
import Login from './Login';
import Register from './Register';
import Upload from './Upload';
import Catalogue from './Catalogue';
import AlbumDetail from './AlbumDetail';
import Achat from './Achat';
import Bibliotheque from './Bibliotheque';
import Dashboard from './Dashboard';
import Nouveautes from './Nouveautes';
import TopVentes from './TopVentes';
import ProfilArtiste from './ProfilArtiste';
import MonCompte from './MonCompte';
import Admin from './Admin';
import Retrait from './Retrait';

function App() {
  const [page, setPage] = useState('accueil');
  const [utilisateur, setUtilisateur] = useState(null);
  const [menuOuvert, setMenuOuvert] = useState(false);

  useEffect(() => {
    const u = localStorage.getItem('utilisateur');
    if (u) setUtilisateur(JSON.parse(u));
  }, [page]);

  const handleDeconnexion = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('utilisateur');
    setUtilisateur(null);
    setPage('accueil');
    setMenuOuvert(false);
  };

  if (page === 'login') return <Login allerVers={setPage} />;
  if (page === 'register') return <Register allerVers={setPage} />;
  if (page === 'upload') return <Upload allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'catalogue') return <Catalogue allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'bibliotheque') return <Bibliotheque allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'dashboard') return <Dashboard allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'nouveautes') return <Nouveautes allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'topventes') return <TopVentes allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'retrait') return <Retrait allerVers={setPage} utilisateur={utilisateur} />;
  if (page === 'mon-compte') return <MonCompte allerVers={setPage} utilisateur={utilisateur} setUtilisateur={setUtilisateur} />;
  if (page === 'admin') return <Admin allerVers={setPage} utilisateur={utilisateur} />;
  if (page && page.startsWith('profil_')) {
    const artisteId = page.split('_')[1];
    return <ProfilArtiste allerVers={setPage} utilisateur={utilisateur} artisteId={artisteId} />;
  }
  if (page && page.startsWith('album_')) {
    const albumId = page.split('_')[1];
    return <AlbumDetail allerVers={setPage} utilisateur={utilisateur} albumId={albumId} />;
  }
  if (page && page.startsWith('achat_')) {
    const musiqueId = page.split('_')[1];
    return <Achat allerVers={setPage} utilisateur={utilisateur} musiqueId={musiqueId} />;
  }

  return (
    <div className="app">
      <header className="header">
        <div className="logo">🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => setPage('accueil')}>Accueil</a>
          <a href="#" onClick={() => setPage('nouveautes')}>Nouveautés</a>
          <a href="#" onClick={() => setPage('topventes')}>Top Ventes</a>
          <a href="#" onClick={() => setPage('catalogue')}>Catalogue</a>
        </nav>
        <div className="auth-buttons">
          {!utilisateur ? (
            <>
              <button className="btn-login" onClick={() => setPage('login')}>
                Connexion
              </button>
              <button className="btn-register" onClick={() => setPage('register')}>
                S'inscrire
              </button>
            </>
          ) : (
            <>
              <span className="user-prenom">👋 {utilisateur.prenom}</span>
              {utilisateur.role === 'artiste' && (
                <button className="btn-dashboard" onClick={() => setPage('upload')}>
                  + Publier
                </button>
              )}
            </>
          )}
        </div>
      </header>

      <main className="hero">
        <h1>La musique africaine<br/>à portée de main</h1>
        <p>Découvrez, écoutez et soutenez les artistes africains</p>
        <div className="hero-boutons">
          <button className="btn-explore" onClick={() => setPage('catalogue')}>
            Explorer la musique
          </button>
          {utilisateur && (
            <button className="btn-bibliotheque-hero" onClick={() => setPage('bibliotheque')}>
              🎵 Ma Bibliothèque
            </button>
          )}
        </div>
      </main>

      {utilisateur && (
        <div className="menu-flottant">
          {menuOuvert && (
            <div className="menu-flottant-items">
              <div className="menu-flottant-prenom">
                👤 {utilisateur.prenom}
              </div>
              {utilisateur.role === 'artiste' && (
                <>
                  <div className="menu-flottant-item" onClick={() => { setPage('dashboard'); setMenuOuvert(false); }}>
                    🎛️ Dashboard
                  </div>
                  <div className="menu-flottant-item" onClick={() => { setPage('mon-compte'); setMenuOuvert(false); }}>
                    ⚙️ Mon Compte
                  </div>
                </>
              )}
              {utilisateur.role === 'acheteur' && (
                <div className="menu-flottant-item" onClick={() => { setPage('bibliotheque'); setMenuOuvert(false); }}>
                  📚 Ma Bibliothèque
                </div>
              )}
              {utilisateur.role === 'admin' && (
                <div className="menu-flottant-item" onClick={() => { setPage('admin'); setMenuOuvert(false); }}>
                  👑 Panel Admin
                </div>
              )}
              <div className="menu-flottant-item deconnexion" onClick={handleDeconnexion}>
                🚪 Déconnexion
              </div>
            </div>
          )}
          <button
            className="btn-flottant"
            onClick={() => setMenuOuvert(!menuOuvert)}
          >
            {menuOuvert ? '✕' : '👤'}
          </button>
        </div>
      )}
    </div>
  );
}

export default App;
